group = "com.sce.forge"
version = "0.1.0"

// Which profile holds the generator is gradle/sce-codegen.gradle.kts's
// business, not this module's — see that file for why no build script
// names one.
apply(from = rootProject.file("gradle/sce-codegen.gradle.kts"))
val sceCodegenRelative: String by rootProject.extra

// Cross-language numerical conformance: invoke the sce-codegen CLI on every
// fixture declared in tests/forge/conformance/fixtures.json AND render the
// test harness itself from the shared Jinja2 template. Both outputs land
// under build/generated/conformance/kotlin/, which is wired into the jvmTest
// source set so the test binary compiles live codegen — no committed goldens
// on the conformance path. See SCE_FORGE.md Section 2.1.
//
// Task is configuration-cache-safe: inputs are declared properties and the
// work happens through ExecOperations.
abstract class GenerateForgeFixtures : DefaultTask() {
    @get:InputFile
    @get:PathSensitive(PathSensitivity.ABSOLUTE)
    abstract val sceCodegen: RegularFileProperty

    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val resourceDir: DirectoryProperty

    @get:InputFile
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val manifest: RegularFileProperty

    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val conformanceTemplateDir: DirectoryProperty

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @get:Inject
    abstract val execOperations: ExecOperations

    @TaskAction
    fun generate() {
        val bin = sceCodegen.get().asFile
        if (!bin.canExecute()) {
            throw GradleException(
                "sce-codegen binary not found or not executable at ${bin.absolutePath}. " +
                "Build it first: " +
                "`cargo build --bin sce-codegen --features cli -p sce-build`",
            )
        }
        val res = resourceDir.get().asFile
        val out = outputDir.get().asFile
        val manifestFile = manifest.get().asFile
        out.deleteRecursively()
        out.mkdirs()

        // Pull the fixture list from sce-codegen itself so this script
        // never has to parse JSON natively. The Rust binary owns the
        // manifest schema (see sce-build/src/conformance.rs).
        //
        // `--language kotlin` applies the matrix-aware filter (kind ships
        // per backend; per-fixture MCU-only codecs like `sce:dma-burst-
        // align` lower to Rust + C11 only and would surface as a
        // `MCU-class kind` error here without pre-filtering — same gate
        // the cmake/python harnesses use).
        //
        // `--documents` answers each fixture's document rather than its
        // name: a path under the resource directory, or the `sce:std/...`
        // name of a standard document, which `generate` reads from the
        // library it embeds. Asked rather than spelled here, so this build
        // does not know where a fixture's document lives.
        val listOut = ByteArrayOutputStream()
        execOperations.exec {
            commandLine(
                bin.absolutePath,
                "list-fixtures",
                "--manifest", manifestFile.absolutePath,
                "--language", "kotlin",
                "--resource-dir", res.absolutePath,
                "--format", "plain",
                "--documents",
            )
            standardOutput = listOut
        }
        val documents = listOut.toString(Charsets.UTF_8)
            .lineSequence()
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .toList()

        // Step 1: per-fixture product code generation.
        for (document in documents) {
            execOperations.exec {
                commandLine(
                    bin.absolutePath,
                    "generate",
                    document,
                    "--language", "kotlin",
                    "--output-dir", out.absolutePath,
                )
            }
        }

        // Step 2: render the NumericalConformanceTest.kt harness from the
        // shared template. No test code is hand-maintained in this module.
        execOperations.exec {
            commandLine(
                bin.absolutePath,
                "generate-conformance",
                "--language", "kotlin",
                "--manifest", manifestFile.absolutePath,
                "--output-dir", out.absolutePath,
            )
        }
    }
}

// The generator is rebuilt from this checkout's sources by the root build's
// `:buildSceCodegen` whenever cargo is on PATH, so a schema change in
// conformance.rs cannot be silently ignored by a jvmTest calling an old binary.
// In CI the task is skipped and the downloaded artifact is used.
val generateForgeFixtures by tasks.registering(GenerateForgeFixtures::class) {
    dependsOn(":buildSceCodegen")
    sceCodegen.set(rootProject.layout.projectDirectory.file(sceCodegenRelative))
    resourceDir.set(rootProject.layout.projectDirectory.dir("tests/forge/resources"))
    manifest.set(rootProject.layout.projectDirectory.file("tests/forge/conformance/fixtures.json"))
    conformanceTemplateDir.set(
        rootProject.layout.projectDirectory.dir("tools/codegen/templates/forge/kotlin/conformance"),
    )
    outputDir.set(layout.buildDirectory.dir("generated/conformance/kotlin"))
}

// Fixtures generated into a separate output dir wired into jvmTest, outside
// the numerical-conformance manifest. RFC variant-default-uniformity (kotlin
// half) generates the 3 default-marker codec fixtures this way: they are
// contract testing (Default emission), not oracle comparison. Mirrors the
// cpp/python/go round-trip atomics. The queue kind's fixtures are generated the
// same way.
abstract class GenerateFixtures : DefaultTask() {
    @get:InputFile
    @get:PathSensitive(PathSensitivity.ABSOLUTE)
    abstract val sceCodegen: RegularFileProperty

    @get:InputDirectory
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val resourceDir: DirectoryProperty

    // The documents under resourceDir this task generates, by name without
    // the extension. Declared by each registration, so one task class serves
    // every set of fixtures that is generated outside the numerical manifest.
    @get:Input
    abstract val fixtures: ListProperty<String>

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @get:Inject
    abstract val execOperations: ExecOperations

    @TaskAction
    fun generate() {
        val bin = sceCodegen.get().asFile
        if (!bin.canExecute()) {
            throw GradleException(
                "sce-codegen binary not found or not executable at ${bin.absolutePath}. " +
                "Build it first: " +
                "`cargo build --bin sce-codegen --features cli -p sce-build`",
            )
        }
        val res = resourceDir.get().asFile
        val out = outputDir.get().asFile
        out.deleteRecursively()
        out.mkdirs()
        for (fixture in fixtures.get()) {
            execOperations.exec {
                commandLine(
                    bin.absolutePath,
                    "generate",
                    res.resolve("$fixture.scxml").absolutePath,
                    "--language", "kotlin",
                    "--output-dir", out.absolutePath,
                )
            }
        }
    }
}

val generateRoundTripFixtures by tasks.registering(GenerateFixtures::class) {
    dependsOn(":buildSceCodegen")
    sceCodegen.set(rootProject.layout.projectDirectory.file(sceCodegenRelative))
    resourceDir.set(rootProject.layout.projectDirectory.dir("tests/forge/resources"))
    fixtures.set(
        listOf(
            "codec_default_marker_arm_a",
            "codec_default_marker_arm_b",
            "codec_variant_default_marker",
        ),
    )
    outputDir.set(layout.buildDirectory.dir("generated/round_trip/kotlin"))
}

// The queue kind's fixtures (SCE Protocol-Synthesis RFC §synth-5-P). They
// assert no numerical oracle value, so the numerical manifest does not list
// them; QueueGeneratedTest compiles what the generator writes for each bounded
// algorithm row against the runtime and uses the queues. The element comes
// first because the queues import its class.
val generateQueueFixtures by tasks.registering(GenerateFixtures::class) {
    dependsOn(":buildSceCodegen")
    sceCodegen.set(rootProject.layout.projectDirectory.file(sceCodegenRelative))
    resourceDir.set(rootProject.layout.projectDirectory.dir("tests/forge/resources"))
    fixtures.set(
        listOf(
            "queue_conformance_event",
            "queue_conformance_spsc",
            "queue_conformance_scq",
        ),
    )
    outputDir.set(layout.buildDirectory.dir("generated/queue/kotlin"))
}

kotlin {
    jvmToolchain(17)
    jvm()
    compilerOptions {
        allWarningsAsErrors.set(true)
    }

    sourceSets {
        val commonMain by getting
        val commonTest by getting {
            dependencies {
                implementation(kotlin("test"))
            }
        }
        val jvmTest by getting {
            dependencies {
                implementation(libs.kotlinx.serialization.json)
            }
            kotlin.srcDir(generateForgeFixtures.map { it.outputDir })
            kotlin.srcDir(generateRoundTripFixtures.map { it.outputDir })
            kotlin.srcDir(generateQueueFixtures.map { it.outputDir })
        }
    }
}

tasks.withType<Test>().configureEach {
    systemProperty("sce.repo.root", rootProject.projectDir.absolutePath)
    // The queue kind's stress runs write their histories to the directory this
    // variable names (QueueHistoryTest). The files are the task's output and
    // Gradle does not know it: a gate that empties the directory and runs the
    // task again would otherwise find it UP-TO-DATE, the tests unrun and the
    // directory empty. Asking for histories therefore always runs the tests.
    if (providers.environmentVariable("SCE_QUEUE_HISTORY_DIR").isPresent) {
        outputs.upToDateWhen { false }
    }
    // The queue contract is read at run time by path, so it is an input like
    // the numerical reference below.
    inputs.file(rootProject.layout.projectDirectory.file("tests/forge/conformance/queue_contract.json"))
        .withPropertyName("queueContract")
        .withPathSensitivity(PathSensitivity.NONE)
    // The generated harness reads the reference cases at run time, by path
    // (harness.kt.jinja2), so to Gradle they are an input like any other: left
    // undeclared, a change to the cases alone leaves jvmTest UP-TO-DATE and the
    // lane green without running them. Measured 2026-09-30, 1800 new cases.
    inputs.file(rootProject.layout.projectDirectory.file("tests/forge/conformance/numerical_reference.json"))
        .withPropertyName("numericalReference")
        .withPathSensitivity(PathSensitivity.NONE)
}
